    ident('editorial-policy', '/about/editorial-policy/', 'How We Write and Check | Relevant Search Media',
        'How we write and check everything we publish. Every page is built from a signed fact register and passes 413 checks before it goes live.', [
        hero([('Home', '/'), ('About', '/about/'), ('Editorial policy', '')], 'Editorial policy', 'How we write and check everything we publish',
             'Every page on this site is written from one signed fact register and is run through the 413 checks of the D’Souza Standard before it goes live. A fact that is not in the register is not used. Thomas D’Souza approves the facts and each step, and every page shows the date it was last reviewed.',
             'Every page is built from a signed fact register and passes the page checks before it goes live.', ctas=(('Book a discovery call', '/book/'), ('See all 413 checks', '/dsouza-equation/standard/'))),
        sec('The rules', 'What rules does every page follow?', ['Six rules. They apply to this site and to every page we write for a client.'],
            table('The six editorial rules and how each is enforced', ('Rule', 'What it means', 'How it is enforced'), [
                ('Facts from the register only', 'Nothing is claimed that has not been signed off', 'Each claim is traced to a register entry before publication'),
                ('No invented proof', 'No made-up reviews, quotes, clients or results', 'Banned outright; real ones only, with their source'),
                ('No client names', 'Results are stated by trade and in ranges', 'No client data appears in public'),
                ('Plain words', 'Written for an owner, not a marketer', 'Reading grade measured on every page'),
                ('Answer first', 'Each page opens with a direct answer', 'Checked in the first 100 words'),
                ('Dated', 'Every page shows when it was published and reviewed', 'Shown on the page and in its markup'),
            ]), more=('See all 413 checks', '/dsouza-equation/standard/'), eid='rules'),
        sec('The register', 'What is the fact register?', ['It is one document listing every fact that may be stated about the company: its founding year, its figures, its commitments, how it works. Thomas signed each entry.', 'To change a fact on the site, the register is changed first. That keeps every page in agreement with every other.'],
            more=('Terms of use', '/terms/'), eid='register'),
        sec('Who writes', 'Who writes the pages, and how is AI used?', ['Pages are researched, drafted and checked by a team of AI agents built and run for this project, working only from the signed register. We say so because readers are entitled to know.', 'Thomas D’Souza approves the facts and each step. No page is published on the strength of a draft alone.'],
            more=('Thomas D’Souza, Founder', '/thomas-dsouza/'), eid='who'),
        sec('The gate', 'What is checked before a page goes live?', ['Each page is fetched as a search engine fetches it and run through the Standard. That covers its title, its answer, its markup, its speed and its reading level, among much else.', 'A page with one failed check is not published. Checks that cannot be tested by machine are marked as untested, never as passed.'],
            more=('The SEO audit, written out: all 413 checks', '/dsouza-equation/standard/'), eid='gate'),
        sec('Sources', 'Where do the claims about search engines come from?', ['From the engines’ own published documentation wherever it exists: Google Search Central, Bing Webmaster Guidelines, OpenAI’s crawler documentation and the like.', 'We use no paid keyword tools. Search demand is read from Google’s own suggestions and from Search Console.'],
            more=('Every AI search engine and search engine we cover', '/dsouza-equation/engines/'), eid='sources'),
        sec('Check a page', 'How can I check a page against this policy?', ['Four steps you can run on any page of this site. For example, try them on the page about a plumber in Miami’s missing searches, or on this one.'],
            steps([('Step 1', 'Find the date', 'Look for the published and reviewed dates near the foot of the page.'),
                   ('Step 2', 'Find the reviewer', 'Each page names who checked it, with a link to his page.'),
                   ('Step 3', 'Trace a figure', 'Pick any number. It should match the same number on every other page.'),
                   ('Step 4', 'Report a fault', 'If something is wrong, tell us. Corrections are listed in public.')]),
            B('Corrections', '/about/corrections/', 'rs-more', mb=0), eid='check'),
        faq('Questions about how we write', 'What do readers ask about how we write?', ASK, [
            ('Is the content on this site written by AI?', 'It is drafted and checked by AI agents built for this project, from a fact register a person signed. Thomas D’Souza approves the facts and each step.\nWe state this openly. What matters to a reader is whether a page is true, and who answers for it.'),
            ('How do you stop errors getting through?', 'In three ways: writers may use only facts from the signed register, every page is run through 413 checks, and Thomas approves each step.\nWhen an error does get through, it is corrected and listed on the corrections page with the date.'),
            ('Do you accept payment to mention products or companies?', 'No. Nothing on this site is sponsored, and no company pays to be mentioned or linked. Tools are named only where a reader needs them to run a check.\nIf that ever changed, the page concerned would say so plainly, at the top.'),
            ('How often are pages reviewed?', 'Each page is reviewed on a schedule, and earlier when a search engine changes how it works. The review date on the page is updated only when a review has actually been done.\nA date is never refreshed simply to look recent.'),
            ('Do the same rules apply to client sites?', 'Yes. A client signs their own fact register before anything is written, and their pages are run through the same checks.\nIt is the main reason their pages do not contradict one another, or claim things the owner would not stand behind.'),
        ]),
        trust(),
        closing('Written from facts, checked before it ships. <span class="gold">Ask us to show you.</span>', 'A discovery call is 20 to 30 minutes with Thomas. He shows you a fact register, the checks a page goes through, and whether your trade is still open in your city.', SMALL),
    ], kw='', example='plumber in miami', trade='register;checks;reviewed', parent='about')

    ident('corrections', '/about/corrections/', 'Corrections | Relevant Search Media',
        'Corrections to this website, listed in public. When we get something wrong, we fix it and record it here with the date and the page concerned.', [
        hero([('Home', '/'), ('About', '/about/'), ('Corrections', '')], 'Corrections', 'Corrections',
             'When something on this site is wrong, we fix it and list it here with the date. A correction is any change to a fact, a figure or a claim; changes of wording that do not alter meaning are not listed. To report an error, write to info@relevantsearchmedia.com and name the page.',
             'When we get something wrong, we fix it and list it here, with the date.', ctas=(('Book a discovery call', '/book/'), ('Ask a question', '/ask/'))),
        sec('The list', 'What has been corrected so far?', ['One entry since this site was published on 28 November 2026. New entries are added at the top.'],
            table('Corrections to this site, newest first', ('Date', 'Where', 'What was corrected'), [
                ('28 Nov 2026', 'Several inner pages', 'Wording that was not in the signed fact register was removed on the day of publication: a description of the discovery call as free, a promised reply time, and two quoted lines the founder had not written.'),
            ]), more=('How we write and check everything we publish', '/about/editorial-policy/'), eid='list'),
        sec('What counts', 'What counts as a correction?', ['Any change to something a reader could rely on: a date, a number, a name, a claim about how an engine works or about what we do.', 'Fixing a typing error or tidying a sentence is not a correction and is not listed.'],
            more=('How we write and check everything we publish', '/about/editorial-policy/'), eid='counts'),
        sec('How fast', 'How quickly is an error fixed?', ['As soon as it is confirmed. The page is corrected first, then the entry is added here, then any other page carrying the same error is fixed.', 'Because every fact comes from one register, a wrong fact is corrected there and the pages follow.'],
            more=('About Relevant Search Media', '/about/'), eid='fast'),
        sec('Engines change', 'What happens when a search engine changes?', ['Then a page can become wrong without anyone having made a mistake. When that happens the page is updated and given a new review date.', 'If the old text would have misled a reader, the change is listed here as well.'],
            more=('Every AI search engine and search engine we cover', '/dsouza-equation/engines/'), eid='engines'),
        sec('Report one', 'How do I report an error?', ['Four steps. For example, if a page said a dentist in Chicago needs something Google no longer requires, we would want to know.'],
            steps([('Step 1', 'Copy the page address', 'So we know exactly where the error is.'),
                   ('Step 2', 'Quote the sentence', 'Paste the words you think are wrong.'),
                   ('Step 3', 'Say what is right', 'Add a source if you have one. It speeds things up.'),
                   ('Step 4', 'Send it', 'Email info@relevantsearchmedia.com or use the Ask page.')]),
            B('Ask a question', '/ask/', 'rs-more', mb=0), eid='report'),
        faq('Questions about corrections', 'What do readers ask about corrections?', ASK, [
            ('Why publish your own mistakes?', 'Because a site that never admits an error cannot be told apart from one that hides them. A dated list lets a reader judge how careful we are.\nIt is also what we ask of client sites, so we hold our own to it.'),
            ('Will I be told if I reported the error?', 'Yes. If you reported it and left a way to reach you, we reply to say what was changed and when, usually with a link to the entry.\nYour name is not published with the correction unless you ask for it to be.'),
            ('Do you delete pages that were wrong?', 'Rarely. A page that was wrong is corrected in place and the change is recorded here, so a reader who saw the old version can find out what changed.\nA page is removed only when its whole subject no longer applies.'),
            ('Are old corrections ever removed from this list?', 'No. Entries stay on this page permanently, newest first. Removing them would defeat the purpose of keeping the list.\nIf the list grows long it will be divided by year, with every entry kept and still open to anyone who wants to read it.'),
            ('What if I disagree with something that is not an error?', 'Tell us all the same. Some statements about search are judgments, and a good argument can change ours.\nWhere a page gives an opinion and not a fact, it should say so. If it does not, that is itself worth reporting.'),
        ]),
        trust(),
        closing('Found something wrong? <span class="gold">Tell us and we will fix it.</span>', 'A discovery call is 20 to 30 minutes with Thomas. He shows you who AI names for your trade in your city, which customer searches you are missing, and whether your trade is still open.', SMALL),
    ], kw='', example='dentist in chicago', trade='corrected;date;error', parent='about', typ='legal')
