    _T = [('plumbers', 'SEO for plumbers'), ('hvac', 'HVAC SEO'), ('electricians', 'SEO for electricians'), ('roofers', 'Roofing SEO'), ('contractors', 'Contractor SEO'), ('landscapers', 'Landscaping SEO'), ('auto-repair', 'Auto repair SEO'),
          ('dentists', 'Dental SEO'), ('medical-clinics', 'Medical SEO'), ('law-firms', 'Law firm SEO'), ('accountants', 'SEO for accountants'), ('realtors', 'Real estate SEO')]
    RELATED = {k: [_T[(i + j) % len(_T)] for j in (1, 2, 3)] for i, (k, n) in enumerate(_T)}   # each trade links to the next three, so every trade page is linked from three others
    def trade(d):
        """One trade page: how its customers search, what is hard, what we do, what proof counts, how assistants answer, a check, FAQs."""
        nm = d['name']; crumbs = [('Home', '/'), ('Industries', '/industries/'), (nm, '')]
        body = [
            hero(crumbs, 'Industry', d['h1'], d['answer'], d['subline'], ctas=(('Book a discovery call', '/book/'), ('Check if your trade is open in your city', '/open-board/'))),
            sec('How they search', d['search_h2'], d['search_p'], table(d['search_caption'], ('Kind of search', 'What they type', 'What it tells you'), d['searches']),
                figure(d['key'], {'kind': 'pairs', 'eyebrow': 'Industry', 'title': d['fig_title'], 'heads': ['The customer wants', 'So they type'], 'items': [[x[0], x[1].split('”')[0].strip('“')] for x in d['searches']]}, d['fig_alt'], d['fig_cap']),
                more=('What your customers search for, by trade and city', '/searches/'), eid='search'),
            sec('What is hard', d['hard_h2'], d['hard_p'], more=d['hard_more'], eid='hard'),
            sec('What we do', d['work_h2'], d['work_p'], table(d['work_caption'], ('The job', 'What we do', 'Part of the equation'), d['work']), more=('Our SEO strategy, day by day', '/dsouza-equation/method/'), eid='work'),
            sec('Proof that counts', d['proof_h2'], d['proof_p'], more=d['proof_more'], eid='proof'),
            sec('AI answers', d['ai_h2'], d['ai_p'], more=('How to get my business recommended by ChatGPT', '/problems/not-recommended-by-chatgpt/'), eid='ai'),
            sec('Check yourself', d['check_h2'], d['check_p'], steps(d['checks']), T('<p>%s</p>' % d['example_p'], 'small rs-note', mt=22, mb=18), B('Why is my business not showing up on Google?', '/problems/not-showing-up-on-google/', 'rs-more', mb=0), eid='check'),
            S([H('Related trades', 'p', 'eyebrow'), C([B(n, '/industries/%s/' % k, 'rsm-btn rsm-btn-ghost') for k, n in RELATED[d['key']]] + [B('SEO by industry: every trade', '/industries/', 'rs-more')], 'rs-actions', 'row', flex_gap=gap(14), flex_wrap='wrap', flex_align_items='center', margin=box(0, 0, 0, 0))], 'rs-sec rs-related', eid='related', pad=(0, 40), pad_m=(0, 28)),
            faq('Questions from ' + d['faq_about'], d['faq_h2'], ASK, d['faqs']),
            trust(),
            closing(d['closing_h2'], d['closing_p'], SMALL),
        ]
        P.append(page(d['key'], d['path'], d['title'], d['desc'], body, parent='industries', kind='service', label=d['title'].split(' | ')[0]))
        GATE[d['path']] = {'kw': d['kw'], 'type': 'service', 'example': d['example'], 'original': '413;v1.0, 23 Nov 2026', 'trade': d['trade']}

