        hard_p=['SEO for realtors is hard because the biggest searches belong to national portals with millions of pages. Competing head-on wastes money.', 'The opening is local depth. A portal cannot say which streets flood, where the school boundary runs or what sold last month and why.'],
        hard_more=('Content marketing', '/services/content-marketing/'),
